const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const moroto = ee.Geometry.Point([34.6667, 2.5333]);
  const region = moroto.buffer(40000); // 40km radius

  // Time periods
  const baselineStart = '2000-08-01';
  const baselineEnd = '2010-08-31';
  const targetStart = '2023-08-01';
  const targetEnd = '2023-08-31';

  // 2. Data Acquisition - MODIS NDVI
  const modisCol = ee.ImageCollection('MODIS/061/MOD13Q1')
    .select(['NDVI', 'DetailedQA']);

  // Filter collections
  const baselineCol = modisCol
    .filterDate(baselineStart, baselineEnd)
    .filter(ee.Filter.calendarRange(8, 8, 'month'));

  const targetCol = modisCol
    .filterDate(targetStart, targetEnd);

  // Check collection sizes
  const baselineSize = baselineCol.size().getInfo();
  const targetSize = targetCol.size().getInfo();

  console.log(`Baseline Images (2000-2010 August): ${baselineSize}`);
  console.log(`Target Images (2023 August): ${targetSize}`);

  if (baselineSize === 0 || targetSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Mask poor quality pixels
  function maskPoorQuality(image) {
    const qa = image.select('DetailedQA');
    // MODIS QA bits: keep only best quality (bits 0-1 = 00)
    const mask = qa.bitwiseAnd(3).eq(0);
    return image.updateMask(mask);
  }

  const baselineMasked = baselineCol.map(maskPoorQuality);
  const targetMasked = targetCol.map(maskPoorQuality);

  // 4. Calculate mean NDVI values
  const baselineMean = baselineMasked.mean().select('NDVI');
  const targetMean = targetMasked.mean().select('NDVI');

  // Check valid pixels
  const baselineCount = baselineMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const targetCount = targetMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Baseline valid pixels: ${baselineCount}`);
  console.log(`Target valid pixels: ${targetCount}`);

  if (baselineCount === 0 || targetCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate mean NDVI values
  const baselineNDVI = baselineMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const targetNDVI = targetMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Baseline NDVI (2000-2010): ${baselineNDVI ? baselineNDVI.toFixed(4) : 'None'}`);
  console.log(`Target NDVI (2023): ${targetNDVI ? targetNDVI.toFixed(4) : 'None'}`);

  // 5. Validation & Final Answer
  if (baselineNDVI === null || targetNDVI === null || 
      isNaN(baselineNDVI) || isNaN(targetNDVI) ||
      baselineNDVI > 1 || targetNDVI > 1 || // NDVI range check
      baselineNDVI < -1 || targetNDVI < -1) {
    console.log("<answer>C3</answer>");
  } else if (targetNDVI < baselineNDVI) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
